# Nginx vhost for set1-owner.test
# Generated by CelikPanel — do not edit by hand / elle düzenlemeyin
# Site ID: 1 · Project type: static
server {
    listen 80;
    listen [::]:80;
    server_name set1-owner.test;

    access_log /var/log/nginx/set1-owner.test-access.log;
    error_log /var/log/nginx/set1-owner.test-error.log;

    # Root-owned validation content only; never tenant public_html.
    location ^~ /.well-known/acme-challenge/ {
        root /var/lib/celikpanel-agent/acme-http-01/subscriptions/2/domains/1;
        try_files $uri =404;
    }

    root /var/www/celikpanel/subscriptions/2/sites/1/public_html;
    index index.html index.htm;

    location / {

        try_files $uri $uri/ =404;
    }
    location ~ \.(php|phtml|phps|php[0-9])$ {
        deny all;
    }
    location ~ /\.(?!well-known).* {
        deny all;
    }
}

# Nginx vhost for set8-a.test
# Generated by CelikPanel — do not edit by hand / elle düzenlemeyin
# Site ID: 2 · Project type: php
server {
    listen 80;
    listen [::]:80;
    server_name set8-a.test;

    access_log /var/log/nginx/set8-a.test-access.log;
    error_log /var/log/nginx/set8-a.test-error.log;

    # Root-owned validation content only; never tenant public_html.
    location ^~ /.well-known/acme-challenge/ {
        root /var/lib/celikpanel-agent/acme-http-01/subscriptions/2/domains/2;
        try_files $uri =404;
    }

    root /var/www/celikpanel/subscriptions/2/sites/2/public_html;
    index index.php index.html index.htm;

    location / {

        try_files $uri $uri/ /index.php?$query_string;
    }
    location ~ \.php$ {
        fastcgi_split_path_info ^(.+?\.php)(/.*)$;
        try_files $fastcgi_script_name =404;
        set $path_info $fastcgi_path_info;
        fastcgi_param PATH_INFO $path_info;
        fastcgi_index index.php;
        include fastcgi.conf;
        fastcgi_pass unix:/var/run/php/php8.4-fpm-site2.sock;
        fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;
        include fastcgi_params;
    }
    location ~ /\.(?!well-known).* {
        deny all;
    }

    # set8: added by the server owner by hand
    location /owner-extra/ {
        return 200 "owner";
    }
}

